1	import { FileSignature, FolderLock, KeyRound, Search, ShieldCheck, UserPlus, Coins, BadgePercent } from "lucide-react";
2	import PageHero from "@/components/ui/PageHero";
3	import HeroSzene from "@/components/Landing/HeroSzene";
4	import { InvestorenDashboard } from "@/components/illustrationen";
5	import Section from "@/components/ui/Section";
6	import SectionHeading from "@/components/ui/SectionHeading";
7	import Steps from "@/components/ui/Steps";
8	import Faq from "@/components/ui/Faq";
9	import CtaBand from "@/components/ui/CtaBand";
10	import Button from "@/components/ui/Button";
11	import Reveal from "@/components/ui/Reveal";
12	import BoerseListe from "@/components/Boerse/BoerseListe";
13	import { abs, SITE, sprachAlternates } from "@/data/site";
14	import { PROVISION, PHASEN } from "@/lib/invest/markt";
15	import { backend, istDemo } from "@/lib/plattform/backend";
16	import { PlattformFehler } from "@/lib/plattform/fehler";
17	
18	export const dynamic = "force-dynamic";
19	
20	const PFAD = "/projektboerse";
21	const TITEL = "Projektbörse: Solarprojekte kaufen & anbieten | ÖkoInvest";
22	const BESCHREIBUNG =
23	  "Solarparks, Agri-PV, Parkplatz-PV und Großspeicher im DACH-Raum: geprüfte Projekte in allen Phasen, NDA per Klick, digitaler Datenraum – für Investoren kostenfrei.";
24	
25	export const metadata = {
26	  title: TITEL,
27	  description: BESCHREIBUNG,
28	  alternates: sprachAlternates("/projektboerse", "/en/project-exchange"),
29	  openGraph: {
30	    type: "website",
31	    url: abs(PFAD),
32	    siteName: "ÖkoInvest",
33	    title: TITEL,
34	    description: BESCHREIBUNG,
35	    images: [{ url: abs("/img/solarpark-reihen.jpg"), width: 1280, height: 852, alt: "Reihen eines Solarparks" }],
36	  },
37	};
38	
39	const ERLAUBTE_FILTER = ["typ", "land", "phase", "mwpMin", "mwpMax", "sortierung"];
40	
41	const FAQ = [
42	  {
43	    q: "Was kostet die Projektbörse?",
44	    a: `Für Investoren ist die Börse ${PROVISION.kaeufer.text.replace("für Investoren ", "")}. Anbieter zahlen eine Erfolgsprovision von ${PROVISION.verkaeufer.text} – keine Einstell- oder Listungsgebühren.`,
45	  },
46	  {
47	    q: "Warum sehe ich keine genaue Lage?",
48	    a: "Öffentlich zeigen wir nur Region, Bundesland bzw. Kanton und Eckdaten. Gemeinde, Flurstücke, Netzbetreiber und Unterlagen sehen registrierte Investoren erst, nachdem sie die Vertraulichkeitsvereinbarung akzeptiert haben und das Backoffice den Datenraum freigegeben hat. Das schützt Flächeneigentümer und Anbieter.",
49	  },
50	  {
51	    q: "Wie werden Projekte geprüft?",
52	    a: "Vor der Veröffentlichung prüft das Backoffice Angaben und Kernunterlagen auf Vollständigkeit und Plausibilität – etwa Flächensicherung, Stand der Bauleitplanung und Netzanschluss. Eine rechtliche und technische Due Diligence ersetzt das nicht; sie bleibt Aufgabe des Käufers.",
53	  },
54	  {
55	    q: "Welche Phasen gibt es?",
56	    a: `Wir unterscheiden ${PHASEN.length} Entwicklungsstände – von „${PHASEN[0].label}“ bis „${PHASEN[PHASEN.length - 1].label}“. Je weiter ein Projekt entwickelt ist, desto geringer das Risiko und desto höher der Preis je kWp.`,
57	  },
58	];
59	
60	export default async function Projektboerse({ searchParams }) {
61	  const sp = await searchParams;
62	  const start = Object.fromEntries(ERLAUBTE_FILTER.map((k) => [k, typeof sp?.[k] === "string" ? sp[k].slice(0, 20) : ""]).filter(([, v]) => v));
63	
64	  let daten = null;
65	  let fehler = "";
66	  try {
67	    daten = await backend().boerse(null, {});
68	  } catch (e) {
69	    fehler = e instanceof PlattformFehler ? e.message : "Die Projektbörse ist vorübergehend nicht erreichbar.";
70	    if (!(e instanceof PlattformFehler)) console.error("[projektboerse]", e);
71	  }
72	  const demo = istDemo();
73	  const kz = daten?.kennzahlen;
74	
75	  const jsonLd = daten && {
76	    "@context": "https://schema.org",
77	    "@type": "CollectionPage",
78	    name: "Projektbörse ÖkoInvest",
79	    url: abs(PFAD),
80	    description: BESCHREIBUNG,
81	    publisher: { "@type": "Organization", name: SITE.firma, url: SITE.url },
82	    mainEntity: {
83	      "@type": "ItemList",
84	      numberOfItems: daten.projekte.length,
85	      itemListElement: daten.projekte.map((p, i) => ({ "@type": "ListItem", position: i + 1, url: abs(`${PFAD}/${p.slug}`), name: p.titel })),
86	    },
87	  };
88	
89	  return (
90	    <>
91	      {jsonLd && <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }} />}
92	      <PageHero
93	        variant="dark"
94	        breadcrumbs={[{ name: "Projektbörse", href: PFAD }]}
95	        eyebrow="Projektbörse DACH"
96	        title={<>Solarprojekte kaufen und verkaufen – <span className="ov-text-gradient-light">geprüft und vertraulich</span></>}
97	        lead="Freiflächen-PV, Agri-PV, Parkplatz-PV und Großspeicher in Deutschland, Österreich und der Schweiz – von der Flächensicherung bis zur Bestandsanlage. Öffentlich als anonymer Teaser, Details erst nach NDA."
98	        actions={[
99	          { label: "Als Investor registrieren", href: "/registrieren?rolle=investor" },
100	          { label: "Projekt anbieten", href: "/projektboerse/anbieten" },
101	        ]}
102	        stats={
103	          kz
104	            ? [
105	                { value: kz.anzahl, label: "Projekte in der Börse" },
106	                { value: kz.mwp, decimals: kz.mwp < 100 ? 1 : 0, suffix: " MWp", label: "Leistung gesamt" },
107	                { value: kz.laender, label: kz.laender === 1 ? "Land" : "Länder" },
108	              ]
109	            : []
110	        }
111	        szene={
112	          <HeroSzene>
113	            <InvestorenDashboard ton="dunkel" animiert />
114	          </HeroSzene>
115	        }
116	      />
117	
118	      <Section tone="sand" space="md" id="projekte">
119	        {demo && (
120	          <p className="mb-6 rounded-2xl bg-sun-300/25 px-5 py-4 text-[14.5px] leading-relaxed text-ink-900 ring-1 ring-inset ring-sun-400/50">
121	            <strong>Vorführdaten:</strong> Die Plattform läuft im Demo-Modus. Alle gezeigten Projekte sind fiktive Beispiele und keine Angebote.
122	          </p>
123	        )}
124	        {fehler ? (
125	          <div className="rounded-3xl bg-white p-8 text-center ring-1 ring-ink-200/70">
126	            <p className="font-display text-[20px] font-bold text-ink-900">Projektbörse derzeit nicht verfügbar</p>
127	            <p className="mt-2 text-[15px] text-ink-600">{fehler}</p>
128	          </div>
129	        ) : (
130	          <BoerseListe projekte={daten.projekte} basisHref={`${PFAD}/`} start={start} />
131	        )}
132	      </Section>
133	
134	      <Section tone="white" space="lg">
135	        <SectionHeading eyebrow="Ablauf" title="Vom Exposé zum Abschluss – alles im Portal" lead="Einheitlicher, nachvollziehbarer Prozess für beide Seiten. Jeder Schritt wird protokolliert." />
136	        <Steps
137	          className="mt-12"
138	          items={[
139	            { icon: UserPlus, title: "Registrieren & Suchprofil", text: "Kostenloses Investorenkonto mit Größe, Phasen, Ländern und Ticket. Passende Projekte zeigen wir zuerst." },
140	            { icon: Search, title: "Exposé prüfen", text: "Eckdaten, Phase, Netzanschluss und Preisindikation – anonym, ohne genaue Lage." },
141	            { icon: KeyRound, title: "NDA per Klick", text: "Vertraulichkeitsvereinbarung im Portal akzeptieren. Nach Freigabe öffnet sich der Datenraum." },
142	            { icon: FileSignature, title: "LOI & Abschluss", text: "Absichtserklärung digital abgeben, Due Diligence, Kaufvertrag – begleitet durch das Backoffice." },
143	          ]}
144	        />
145	      </Section>
146	
147	      <Section tone="ink" space="lg">
148	        <div className="grid gap-5 lg:grid-cols-2">
149	          <Reveal className="rounded-[2rem] bg-white p-8 ring-1 ring-ink-200/70 md:p-10">
150	            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-ov-50 text-ov-600"><ShieldCheck aria-hidden="true" className="h-6 w-6" /></span>
151	            <h2 className="ov-h3 mt-6 text-ink-900">Für Investoren: kostenfrei</h2>
152	            <p className="mt-3 text-[16px] leading-relaxed text-ink-600">Suchprofil, Merkliste, NDA und Datenraum sind für Investoren kostenfrei. Sie sehen Projekte aus der Entwicklung der ÖKOVOLT Gruppe und von weiteren Entwicklern.</p>
153	            <ul className="mt-5 space-y-2 text-[15px] text-ink-700">
154	              <li className="flex gap-2"><FolderLock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" /> Datenraum mit Download-Protokoll</li>
155	              <li className="flex gap-2"><Search aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" /> Matching nach Suchprofil</li>
156	            </ul>
157	            <Button href="/registrieren?rolle=investor" className="mt-7" pfeil>Investorenkonto anlegen</Button>
158	          </Reveal>
159	          <Reveal delay={100} className="ov-noise relative overflow-hidden rounded-[2rem] bg-navy-950 p-8 text-white md:p-10">
160	            <div aria-hidden="true" className="absolute -right-20 -top-20 h-64 w-64 rounded-full bg-ov-500/30 blur-[90px]" />
161	            <span className="relative flex h-12 w-12 items-center justify-center rounded-2xl bg-white/10 text-ov-300"><BadgePercent aria-hidden="true" className="h-6 w-6" /></span>
162	            <h2 className="ov-h3 relative mt-6 text-white">Für Projektentwickler: Provision nur bei Erfolg</h2>
163	            <p className="relative mt-3 text-[16px] leading-relaxed text-white/70">Einstellen, prüfen lassen, vertraulich vermarkten. Die Provision beträgt {PROVISION.verkaeufer.text} – keine Listungsgebühren.</p>
164	            <ul className="relative mt-5 space-y-2 text-[15px] text-white/80">
165	              <li className="flex gap-2"><Coins aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-300" /> Transparente Statistik: Aufrufe, Merker, NDA-Anfragen</li>
166	              <li className="flex gap-2"><ShieldCheck aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-300" /> Anonymer Teaser, Datenraum nur nach NDA</li>
167	            </ul>
168	            <Button href="/projektboerse/anbieten" variant="white" className="relative mt-7" pfeil>Projekt anbieten</Button>
169	          </Reveal>
170	        </div>
171	      </Section>
172	
173	      <Section tone="white" space="lg">
174	        <div className="grid gap-12 lg:grid-cols-[1fr_1.4fr]">
175	          <SectionHeading eyebrow="Häufige Fragen" title="Projektbörse: das Wichtigste in Kürze" />
176	          <Faq items={FAQ} />
177	        </div>
178	      </Section>
179	
180	      <CtaBand
181	        eyebrow="Projektbörse"
182	        title="Das passende Projekt nicht dabei?"
183	        text="Legen Sie ein Suchprofil an. Neue Projekte, die zu Ihren Kriterien passen, sehen Sie im Portal zuerst."
184	        primary={{ label: "Suchprofil anlegen", href: "/registrieren?rolle=investor" }}
185	        secondary={{ label: "Für Investoren", href: "/investoren" }}
186	      />
187	    </>
188	  );
189	}
190	"use client";
191	
192	// Filter-Insel der Projektbörse: die Liste wird serverseitig vollständig gerendert
193	// (SEO), Filter und Sortierung laufen im Browser und stehen in der URL.
194	
195	import { useEffect, useMemo, useState } from "react";
196	import Link from "next/link";
197	import { Columns3, SlidersHorizontal, X, SearchX, List, Map as KarteIcon } from "lucide-react";
198	import { cn } from "@/components/ui/cn";
199	import ProjektKarte from "./ProjektKarte";
200	import MerkenKnopf from "./MerkenKnopf";
201	import KarteDach from "./KarteDach"; // Deal-Room-Team: Kartenansicht (Filter synchron)
202	import { LAENDER, PROJEKT_TYPEN } from "@/lib/plattform/konstanten";
203	import { statusInfo } from "@/lib/plattform/prozesse";
204	import { PHASEN } from "@/lib/invest/markt";
205	import { eingabe, auswahlfeld } from "@/components/Portal/felder";
206	
207	const LEER = { typ: "", land: "", phase: "", mwpMin: "", mwpMax: "", sortierung: "neu", ansicht: "alle", darstellung: "liste", region: "" };
208	
209	function chipKlasse(aktiv) {
210	  return cn(
211	    "inline-flex h-9 items-center rounded-full px-3.5 text-[13.5px] font-medium ring-1 ring-inset transition-colors",
212	    aktiv ? "bg-navy-900 text-white ring-navy-900" : "bg-white text-ink-700 ring-ink-200 hover:ring-ink-300"
213	  );
214	}
215	
216	export default function BoerseListe({ projekte = [], basisHref = "/projektboerse/", portal = false, start = {}, karte = true }) {
217	  const [f, setF] = useState({ ...LEER, ...start });
218	  const [offen, setOffen] = useState(false);
219	  const setze = (k, v) => setF((x) => ({ ...x, [k]: v }));
220	
221	  useEffect(() => {
222	    const q = new URLSearchParams();
223	    for (const [k, v] of Object.entries(f)) if (v && v !== LEER[k]) q.set(k, v);
224	    const url = `${window.location.pathname}${q.toString() ? `?${q}` : ""}`;
225	    window.history.replaceState(window.history.state, "", url);
226	  }, [f]);
227	
228	  const basisListe = useMemo(() => {
229	    const num = (v) => (v === "" ? null : Number(String(v).replace(",", ".")));
230	    const min = num(f.mwpMin);
231	    const max = num(f.mwpMax);
232	    let l = projekte.filter(
233	      (p) =>
234	        (!f.typ || p.typ === f.typ) &&
235	        (!f.land || p.land === f.land) &&
236	        (!f.phase || p.phase === f.phase) &&
237	        (min === null || p.mwp >= min) &&
238	        (max === null || p.mwp <= max) &&
239	        (f.ansicht !== "merkliste" || p.meinInteresse?.gemerkt) &&
240	        (f.ansicht !== "aktiv" || (p.meinInteresse && p.meinInteresse.status !== "gemerkt"))
241	    );
242	    if (f.sortierung === "gross") l = [...l].sort((a, b) => b.mwp - a.mwp);
243	    else if (f.sortierung === "passung") l = [...l].sort((a, b) => (b.matching?.score || 0) - (a.matching?.score || 0));
244	    else if (f.sortierung === "phase") l = [...l].sort((a, b) => PHASEN.findIndex((x) => x.id === b.phase) - PHASEN.findIndex((x) => x.id === a.phase));
245	    return l;
246	  }, [projekte, f]);
247	  // Region (Bundesland/Kanton) aus der Karte – wirkt auf die Liste, die Karte zeigt alle übrigen Treffer
248	  const liste = useMemo(() => (f.region ? basisListe.filter((p) => p.bundesland === f.region) : basisListe), [basisListe, f.region]);
249	
250	  const aktiveFilter = ["typ", "land", "phase", "mwpMin", "mwpMax", "region"].filter((k) => f[k]).length;
251	  const gemerkt = projekte.filter((p) => p.meinInteresse?.gemerkt).length;
252	
253	  const filter = (
254	    <div className="space-y-5">
255	      <fieldset>
256	        <legend className="mb-2 text-[12.5px] font-semibold uppercase tracking-wider text-ink-500">Projekttyp</legend>
257	        <div className="flex flex-wrap gap-2">
258	          <button type="button" className={chipKlasse(!f.typ)} aria-pressed={!f.typ} onClick={() => setze("typ", "")}>Alle</button>
259	          {Object.entries(PROJEKT_TYPEN).map(([k, v]) => (
260	            <button key={k} type="button" className={chipKlasse(f.typ === k)} aria-pressed={f.typ === k} onClick={() => setze("typ", f.typ === k ? "" : k)}>{v}</button>
261	          ))}
262	        </div>
263	      </fieldset>
264	      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
265	        <fieldset>
266	          <legend className="mb-2 text-[12.5px] font-semibold uppercase tracking-wider text-ink-500">Land</legend>
267	          <div className="flex flex-wrap gap-2">
268	            <button type="button" className={chipKlasse(!f.land)} aria-pressed={!f.land} onClick={() => setze("land", "")}>Alle</button>
269	            {Object.keys(LAENDER).map((k) => (
270	              <button key={k} type="button" className={chipKlasse(f.land === k)} aria-pressed={f.land === k} onClick={() => setze("land", f.land === k ? "" : k)} title={LAENDER[k]}>{k}</button>
271	            ))}
272	          </div>
273	        </fieldset>
274	        <div>
275	          <label htmlFor="filter-phase" className="mb-2 block text-[12.5px] font-semibold uppercase tracking-wider text-ink-500">Phase</label>
276	          <select id="filter-phase" className={cn(auswahlfeld, "h-10")} value={f.phase} onChange={(e) => setze("phase", e.target.value)}>
277	            <option value="">Alle Phasen</option>
278	            {PHASEN.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
279	          </select>
280	        </div>
281	        <div>
282	          <p id="filter-mwp" className="mb-2 text-[12.5px] font-semibold uppercase tracking-wider text-ink-500">Leistung (MWp)</p>
283	          <div className="flex items-center gap-2" role="group" aria-labelledby="filter-mwp">
284	            <input aria-label="MWp von" inputMode="decimal" placeholder="von" className={cn(eingabe, "h-10")} value={f.mwpMin} onChange={(e) => setze("mwpMin", e.target.value)} />
285	            <span className="text-ink-400">–</span>
286	            <input aria-label="MWp bis" inputMode="decimal" placeholder="bis" className={cn(eingabe, "h-10")} value={f.mwpMax} onChange={(e) => setze("mwpMax", e.target.value)} />
287	          </div>
288	        </div>
289	        <div>
290	          <label htmlFor="filter-sort" className="mb-2 block text-[12.5px] font-semibold uppercase tracking-wider text-ink-500">Sortierung</label>
291	          <select id="filter-sort" className={cn(auswahlfeld, "h-10")} value={f.sortierung} onChange={(e) => setze("sortierung", e.target.value)}>
292	            <option value="neu">Neueste zuerst</option>
293	            <option value="gross">Größte zuerst</option>
294	            <option value="phase">Am weitesten entwickelt</option>
295	            {portal && <option value="passung">Beste Passung (Suchprofil)</option>}
296	          </select>
297	        </div>
298	      </div>
299	    </div>
300	  );
301	
302	  return (
303	    <div>
304	      {portal && (
305	        <div className="mb-5 flex flex-wrap items-center gap-2">
306	        <div className="flex flex-wrap gap-2" role="group" aria-label="Ansicht">
307	          {[
308	            ["alle", "Alle Projekte"],
309	            ["merkliste", "Merkliste"],
310	            ["aktiv", "NDA & Datenräume"],
311	          ].map(([k, v]) => (
312	            <button key={k} type="button" className={chipKlasse(f.ansicht === k)} aria-pressed={f.ansicht === k} onClick={() => setze("ansicht", k)}>{v}</button>
313	          ))}
314	        </div>
315	          {gemerkt >= 2 && (
316	            <Link href="/portal/boerse/vergleich" className="inline-flex h-9 items-center gap-1.5 rounded-full bg-ov-600 px-3.5 text-[13.5px] font-semibold text-white hover:bg-ov-700 sm:ml-auto">
317	              <Columns3 aria-hidden="true" className="h-4 w-4" /> Merkliste vergleichen ({Math.min(4, gemerkt)})
318	            </Link>
319	          )}
320	        </div>
321	      )}
322	
323	      <div className="mb-6 rounded-3xl bg-white p-4 ring-1 ring-ink-200/70 md:p-6">
324	        <div className="flex items-center justify-between gap-3 md:hidden">
325	          <button type="button" onClick={() => setOffen((o) => !o)} aria-expanded={offen} aria-controls="boerse-filter" className="inline-flex h-10 items-center gap-2 rounded-full bg-sand-50 px-4 text-[14px] font-semibold text-ink-800 ring-1 ring-inset ring-ink-200">
326	            <SlidersHorizontal aria-hidden="true" className="h-4 w-4" /> Filter{aktiveFilter ? ` (${aktiveFilter})` : ""}
327	          </button>
328	          <p className="text-[13.5px] text-ink-500" aria-live="polite">{liste.length} Projekte</p>
329	        </div>
330	        <div id="boerse-filter" className={cn("md:block", offen ? "mt-4 block" : "hidden")}>{filter}</div>
331	        <div className="mt-4 hidden items-center justify-between border-t border-ink-100 pt-4 md:flex">
332	          <p className="text-[14px] text-ink-600" aria-live="polite"><span className="ov-num font-semibold text-ink-900">{liste.length}</span> {liste.length === 1 ? "Projekt" : "Projekte"} gefunden</p>
333	          {aktiveFilter > 0 && (
334	            <button type="button" onClick={() => setF((x) => ({ ...LEER, sortierung: x.sortierung, ansicht: x.ansicht, darstellung: x.darstellung }))} className="inline-flex items-center gap-1.5 text-[13.5px] font-semibold text-ink-600 hover:text-ink-900">
335	              <X aria-hidden="true" className="h-4 w-4" /> Filter zurücksetzen
336	            </button>
337	          )}
338	        </div>
339	      </div>
340	
341	      {karte && (
342	        <div className="mb-5 flex flex-wrap items-center gap-2">
343	          <div className="inline-flex rounded-full bg-white p-1 ring-1 ring-inset ring-ink-200" role="group" aria-label="Darstellung">
344	            {[["liste", "Liste", List], ["karte", "Karte", KarteIcon]].map(([k, label, Icon]) => (
345	              <button key={k} type="button" aria-pressed={f.darstellung === k} onClick={() => setze("darstellung", k)} className={cn("inline-flex h-8 items-center gap-1.5 rounded-full px-3.5 text-[13.5px] font-semibold transition-colors", f.darstellung === k ? "bg-navy-900 text-white" : "text-ink-700 hover:bg-ink-50")}>
346	                <Icon aria-hidden="true" className="h-4 w-4" /> {label}
347	              </button>
348	            ))}
349	          </div>
