484	// Screenshots einer Seite in mehreren Breiten, sammelt Konsolenfehler.
485	// Aufruf: node shot.mjs <url> <ausgabeordner> [breiten, z. B. 1440,768,390] [--full | --tiles | --el=<css>]
486	//   --el=<css> jedes passende Element einzeln aufnehmen, z. B. --el=[data-abschnitt=hero]
487	//   --full   eine Ganzseiten-Aufnahme (Reveal-Inhalte werden vorher sichtbar gemacht)
488	//   --tiles  eine Aufnahme je Bildschirmhöhe beim echten Scrollen (wie ein Mensch sieht)
489	import { chromium } from "playwright";
490	import { mkdirSync } from "node:fs";
491	
492	const [url, out = "./shots", breitenArg = "1440,390", ...rest] = process.argv.slice(2);
493	const full = rest.includes("--full");
494	const tiles = rest.includes("--tiles");
495	mkdirSync(out, { recursive: true });
496	
497	const browser = await chromium.launch();
498	for (const w of breitenArg.split(",").map(Number)) {
499	  const h = w < 700 ? 844 : 900;
500	  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
501	  const fehler = [];
502	  page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
503	  page.on("pageerror", (e) => fehler.push(String(e)));
504	  await page.goto(url, { waitUntil: "networkidle", timeout: 120000 });
505	  await page.waitForTimeout(600);
506	  // Cookie-Banner schließen, damit er keine Inhalte verdeckt
507	  await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 8000 }).catch(() => {});
508	  await page.waitForTimeout(400);
509	  const gesamt = await page.evaluate(() => document.documentElement.scrollHeight);
510	
511	  const elArg = rest.find((a) => a.startsWith("--el="));
512	  if (elArg) {
513	    // einzelne Elemente (z. B. --el=[data-abschnitt=hero]) nacheinander ins Bild scrollen und aufnehmen
514	    const sel = elArg.slice(5);
515	    const els = await page.locator(sel).all();
516	    if (!els.length) console.log(`  ! kein Element für ${sel}`);
517	    let n = 0;
518	    for (const el of els) {
519	      await el.scrollIntoViewIfNeeded();
520	      // langsam durch das Element scrollen, damit Reveal-Inhalte sichtbar werden
521	      const box = await el.boundingBox();
522	      if (box) for (let d = 0; d < box.height; d += 300) { await page.mouse.wheel(0, 300); await page.waitForTimeout(100); }
523	      await page.waitForTimeout(900);
524	      const name = sel.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
525	      const datei = `${out}/w${w}-${name}${els.length > 1 ? "-" + n : ""}.png`;
526	      n++;
527	      await el.screenshot({ path: datei });
528	      console.log(datei);
529	    }
530	  } else if (tiles) {
531	    let n = 0;
532	    for (let y = 0; y < gesamt; y += h - 80) {
533	      await page.evaluate((yy) => window.scrollTo(0, yy), y);
534	      await page.waitForTimeout(900);
535	      const datei = `${out}/w${w}-${String(n++).padStart(2, "0")}.png`;
536	      await page.screenshot({ path: datei });
537	      console.log(datei);
538	    }
539	  } else {
540	    // langsam durchscrollen, damit Reveal-Beobachter auslösen
541	    for (let y = 0; y < gesamt; y += 300) { await page.evaluate((yy) => window.scrollTo(0, yy), y); await page.waitForTimeout(120); }
542	    await page.evaluate(() => window.scrollTo(0, 0));
543	    await page.waitForTimeout(800);
