                    {aktiv && zeigeMarke && (
                      <span aria-hidden="true" className="absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-sun-300 ring-[3px] ring-navy-950" style={{ left: pos(preisProKwp) }} />
