    "St. Gallen": [9.2, 47.2], Tessin: [8.8, 46.3], Thurgau: [9.1, 47.55], Uri: [8.6, 46.75], Waadt: [6.6, 46.6], Wallis: [7.6, 46.2], Zug: [8.5, 47.15], Zürich: [8.65, 47.4],
  },
