            {ERTRAG_STUFEN.map((s) => <span key={s.fill} className="h-full w-7" style={{ background: s.fill }} />)}
          </span>
          <span className="ov-num">{fmt(ERTRAG_MAX)} kWh/kWp</span>
        </span>
        <span>Schematisch, nicht maßstäblich · PVGIS</span>
      </figcaption>
    </figure>
  );
}

